#!/usr/bin/env node
// Regenerates lib/access-policy.ts from data/access-policy.json (a copy of the front end's src/data/access-policy.json).
//   node scripts/gen-access-policy.mjs [path/to/front/src/data/access-policy.json]
import { readFileSync, writeFileSync, copyFileSync } from 'node:fs';
const here = new URL('..', import.meta.url);
const src = process.argv[2];
if (src) copyFileSync(src, new URL('data/access-policy.json', here));
const json = JSON.parse(readFileSync(new URL('data/access-policy.json', here), 'utf8'));
writeFileSync(new URL('lib/access-policy.ts', here),
  '// GENERATED by scripts/gen-access-policy.mjs from data/access-policy.json — do not edit by hand.\n' +
  `export const POLICY = ${JSON.stringify(json, null, 2)} as const;\n`);
console.log('lib/access-policy.ts written');
